declare(strict_types=1);

namespace Guard\Policy;

use Guard\Diagnostic\Finding;
use Guard\Structure\Document\Constraint;
use Guard\Structure\Document\DataDocument;
use Guard\Structure\Document\PhpDocument;
use Guard\Structure\Document\Selection;
use Guard\Structure\Document\XmlDocument;
use JsonException;

/**
 * Applies a rule to the selected value without exposing actual configuration values.
 */
final class RuleEvaluator
{
    /**
     * Checks a field, treating numeric XML text as numbers only for bound assertions.
     * @throws JsonException
     */
    public function accepts(Rule $rule, DataDocument|XmlDocument|PhpDocument $document): bool
    {
        $selection = $document->read($rule->select);
        if ($document instanceof XmlDocument && $selection->exists && is_string($selection->value)
            && is_numeric($selection->value) && !array_key_exists('equals', $rule->assertions) && !array_key_exists('one_of', $rule->assertions)) {
            $selection = new Selection(true, (float) $selection->value);
        }
        return (new Constraint())->accepts($selection, $rule->assertions);
    }
    /**
     * Describes the rule and its repair without printing the current value.
     * @throws JsonException
     */
    public function finding(Rule $rule, bool $repairAttempted = false): Finding
    {
        $message = (new Diagnostic\FieldMessage())->render($rule);
        if ($repairAttempted && $rule->repairable) {
            $message = $rule->select . ' in ' . $rule->file . ' still violates its constraints after the configured repair. '
                . 'Resolve the conflicting assertions or repairs for this file in guard.yaml before running guard fix again.';
        }
        return new Finding($rule->file, $rule->id, $rule->level, $message, $rule->repairable && !$repairAttempted);
    }
}
<?php

declare(strict_types=1);

namespace Guard\Policy;

use JsonException;
use stdClass;

/**
 * A required constraint or a non-fatal recommendation for a document field.
 *
 * @property-read string $id
 * @property-read string $file
 * @property-read string $format
 * @property-read string $select
 * @property-read string $level
 * @property-read array<string, mixed> $assertions
 * @property-read mixed $repair
 * @property-read string $message
 * @property-read bool $repairable
 */
final class Rule
{
    /** @readonly */
    private string $assertionsJson;

    /** @readonly */
    private string $repairJson;

    /**
     * Creates the immutable value.
     * @param string $id
     * @param string $file
     * @param string $format
     * @param string $select
     * @param string $level
     * @param array<string, mixed> $assertions
     * @param mixed $repair
     * @param bool $repairable
     * @throws JsonException
     */
    public function __construct(
        /** @readonly */
        private string $id,
        /** @readonly */
        private string $file,
        /** @readonly */
        private string $format,
        /** @readonly */
        private string $select,
        /** @readonly */
        private string $level,
        array $assertions,
        mixed $repair,
        /** @readonly */
        private bool $repairable,
        /** @readonly */
        private string $message = '',
    ) {
        $this->repairJson = json_encode($repair, JSON_THROW_ON_ERROR | JSON_PRESERVE_ZERO_FRACTION);
        $this->assertionsJson = json_encode($assertions, JSON_THROW_ON_ERROR | JSON_PRESERVE_ZERO_FRACTION);
    }

    /** Returns a declared immutable property.
     * @return mixed
     * @throws JsonException
     */
    public function __get(string $name): mixed
    {
        if ($name === 'assertions') {
            $assertions = json_decode($this->assertionsJson, false, 512, JSON_THROW_ON_ERROR);
            return $assertions instanceof stdClass ? get_object_vars($assertions) : [];
        }
        return match ($name) {
            'id' => $this->id,
            'file' => $this->file,
            'format' => $this->format,
            'select' => $this->select,
            'level' => $this->level,
            'repair' => json_decode($this->repairJson, false, 512, JSON_THROW_ON_ERROR),
            'repairable' => $this->repairable,
            'message' => $this->message,
            default => null,
        };
    }
}
